{
  "assessment": "This change introduces a new `src/lib.rs` defining `split_bill` using plain integer division (`total_cents / people`). It does not fix the stated bug; remainders are silently discarded, so shares will sum to less than `total_cents`. The acceptance test passes only because it tests a perfectly divisible case (100 ÷ 4).",
  "findings": [
    {
      "actual": "[51, 51]",
      "at": "src/lib.rs:split_bill",
      "call": "split_bill(103, 2)",
      "defect": "Integer division truncates the remainder instead of distributing it across shares. The returned vector sums to 102 instead of 103.",
      "expected": "[51, 52] (or any partition summing to 103)"
    }
  ]
}
